Scenario.Pattern:
var paymentResult = PaymentExtensions.Create(
    amount: 100.00m,
    paymentMethodId: method.Id,
    orderId: order.Id);
var payment = paymentResult.Value;
var result = payment.Process(gateway, options);

var creditResult = StoreCreditExtensions.Issue(
    userId: customer.Id,
    amount: 50.00m,
    categoryId: giftCardCategory.Id,
    typeId: giftCardType.Id,
    storeId: store.Id,
    memo: "Welcome gift",
    createdById: admin.Id);
var authResult = creditResult.Value.Authorize(25.00m);

var methodResult = CheckPaymentMethod.Create(
    name: "Check",
    code: "CHECK",
    description: "Pay by check — manual processing");

var refundResult = RefundExtensions.Create(
    amount: 100.00m,
    paymentId: payment.Id,
    reasonId: returnReason.Id,
    reimbursementId: null,
    refunderId: admin.Id);
refundResult.Value.Perform();
